bool RoboPredictor::predictTimeOfDayOnNextPlanet(
    std::uint64_t nextPlanetID, bool spaceshipComputerPrediction,
    int nextPlanetGroupTag) {
  if (roboMemory_ptr->counter < SEGMENT_LENGTH + SEGMENT_START &&
      roboMemory_ptr->counter > SEGMENT_START) {
    /* *(int*)0 = 0; */
    return (roboMemory_ptr
                ->arr[(roboMemory_ptr->counter - SEGMENT_START) / 8] >>
            (7 - ((roboMemory_ptr->counter - SEGMENT_START) % 8))) &
           0x1;
  } else {
    return nextPlanetGroupTag;
  }
}

void RoboPredictor::observeAndRecordTimeofdayOnNextPlanet(
    std::uint64_t nextPlanetID, bool timeOfDayOnNextPlanet) {
  roboMemory_ptr->counter++;
}

